// byName lets a caller look a glyph up the way the icon set names it, which
// keeps the mapping from meaning to picture readable at the call site.
var byName = map[string]string{
	"clock-circle":             ClockCircle,
	"circle-half-dotted-check": CircleHalfCheck,
	"lock-circle":              LockCircle,
	"check-circle":             CheckCircle,
	"close-circle":             CloseCircle,
	"nodes":                    Nodes,
	"hashtag":                  Hashtag,
	"code-circle":              CodeCircle,
	"user":                     User,
	"bookmark":                 Bookmark,
	"note":                     Note,
	"tree":                     Tree,
	"document-code":            DocumentCode,
	"code-square":              CodeSquare,
	"monitor":                  Monitor,
	"layers":                   Layers,
	"eye":                      Eye,
	"share":                    Share,
	"shield-check":             ShieldCheck,
	"package":                  Package,
	"flash":                    Flash,
}

// Get returns the markup for a glyph. The second result reports whether the
// name is known; an unknown name draws nothing rather than a broken box.
func Get(name string) (string, bool) {
	body, ok := byName[name]
	return body, ok
}

// Names lists every vendored glyph, for tests that check the set stays whole.
func Names() []string {
	out := make([]string, 0, len(byName))
	for name := range byName {
		out = append(out, name)
	}
	return out
}
